ctx.fillRect(0, 0, W, H);

const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

const colors = [
  '#ffd1dc', // pastel pink
  '#c9e9ff', // pastel blue
  '#d0f4de', // pastel green
  '#fff9b7', // pastel yellow
  '#e6c5ff', // pastel purple
  '#ffb3c6'  // pastel rose
];

for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 30;
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fillStyle = colors[i];
  ctx.fill();

  // Add a subtle border to each circle
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2;
  ctx.stroke();
}
